    41	    const covered = state.coveredTopics.find((ct) => ct.slug === topicSlug || ct.slug === fb.topic);
    42	    const session =
    43	      state.sessions.find((s) => s.topicsCovered.includes(topicSlug)) ?? null;
    44	
    45	    let sessionDurationMs: number | null = null;
    46	    if (session?.startedAt && session?.endedAt) {
    47	      sessionDurationMs =
    48	        new Date(session.endedAt).getTime() -
    49	        new Date(session.startedAt).getTime();
    50	    }
    51	
    52	    outcomes.push({
    53	      learnerId: state.profile.id,
    54	      topic: topicSlug,
    55	      feedbackSignal: fb.signal,
