    61	  }
    62	
    63	  for (const quizResult of state.quizResults ?? []) {
    64	    const topicSlug = resolveTopic(quizResult.topic).slug;
    65	    const covered = state.coveredTopics.find((ct) => ct.slug === topicSlug);
    66	    outcomes.push({
