    97	async function readLearnerMessages(cwd: string): Promise<string[]> {
    98	  const dir = sessionsDir(cwd);
    99	  const entries = await readdir(dir, { withFileTypes: true }).catch(() => []);
   100	  const messages: string[] = [];
   101	
   102	  for (const entry of entries) {
   103	    if (!entry.isFile() || !entry.name.endsWith(".json")) continue;
   104	    const fullPath = join(dir, entry.name);
   105	    try {
   106	      const parsed = JSON.parse(await readFile(fullPath, "utf8")) as { messages?: unknown[] };
   107	      for (const message of parsed.messages ?? []) {
   108	        if (!message || typeof message !== "object") continue;
   109	        const role = (message as { role?: unknown }).role;
   110	        if (role !== "user" && role !== "user-with-attachments") continue;
   111	        const text = messageText(message);
   112	        if (text) messages.push(text);
   113	      }
   114	    } catch {
   115	      continue;
   116	    }
   117	  }
   118	
   119	  return messages;
