   121	
   122	function messageText(message: unknown): string {
   123	  const content = (message as { content?: unknown }).content;
   124	  if (typeof content === "string") return content.trim();
   125	  if (Array.isArray(content)) {
   126	    return content
   127	      .map((item) => {
   128	        if (typeof item === "string") return item;
   129	        if (item && typeof item === "object" && typeof (item as { text?: unknown }).text === "string") {
   130	          return (item as { text: string }).text;
   131	        }
   132	        return "";
   133	      })
   134	      .filter(Boolean)
   135	      .join(" ")
   136	      .trim();
   137	  }
   138	  return "";
   139	}
