   231	function classifyDominantSignal(simulations: TeachingSimulation[], kind: "strength" | "weakness"): string {
   232	  if (simulations.length === 0) return "no learner feedback";
   233	  const metrics = {
   234	    intuitionFit: mean(simulations.map((entry) => entry.breakdown.intuitionFit)),
   235	    rigorFit: mean(simulations.map((entry) => entry.breakdown.rigorFit)),
   236	    dialogueFit: mean(simulations.map((entry) => entry.breakdown.dialogueFit)),
   237	    diagramFit: mean(simulations.map((entry) => entry.breakdown.diagramFit)),
   238	    practiceFit: mean(simulations.map((entry) => entry.breakdown.practiceFit)),
   239	    reflectionFit: mean(simulations.map((entry) => entry.breakdown.reflectionFit)),
   240	    overload: mean(simulations.map((entry) => entry.breakdown.overload))
   241	  };
   242	  const ordered = Object.entries(metrics).sort((left, right) =>
   243	    kind === "strength" ? right[1] - left[1] : left[1] - right[1]
   244	  );
   245	  const [name] = ordered[0] ?? ["unknown"];
   246	  return name;
   247	}
