   249	export function summarizeTopic(topic: TopicDefinition, simulations: TeachingSimulation[], traceLimit: number): TopicBenchmark {
   250	  const ranked = [...simulations].sort((left, right) => right.score - left.score);
   251	  
   252	  const scores = simulations.map((entry) => entry.score).filter(s => !Number.isNaN(s));
   253	  const meanScore = mean(scores) * 100;
   254	
   255	  return {
   256	    topic,
   257	    learnerCount: simulations.length,
   258	    meanScore,
   259	    meanMasteryGain: mean(simulations.map((entry) => entry.masteryGain).filter(m => !Number.isNaN(m))),
   260	    meanRetention: mean(simulations.map((entry) => entry.retention).filter(r => !Number.isNaN(r))),
   261	    meanEngagement: mean(simulations.map((entry) => entry.engagement).filter(e => !Number.isNaN(e))),
   262	    meanTransfer: mean(simulations.map((entry) => entry.transfer).filter(t => !Number.isNaN(t))),
   263	    meanConfusion: mean(simulations.map((entry) => entry.confusion).filter(c => !Number.isNaN(c))),
   264	    topLearners: ranked.slice(0, traceLimit),
   265	    strugglingLearners: ranked.slice(-traceLimit).reverse(),
   266	    dominantStrength: classifyDominantSignal(simulations, "strength"),
   267	    dominantWeakness: classifyDominantSignal(simulations, "weakness")
   268	  };
   269	}
