   277	export async function runBenchmarkSuite(
   278	  cwd: string,
   279	  policy: TeacherPolicy,
   280	  focusTopic?: string,
   281	  seed = 20260401,
   282	  traceLimit = 3,
   283	  weights: SimulationWeights = DEFAULT_WEIGHTS,
   284	  learnerState?: LearnerState
