   289	  const hasLearnerContext = learnerState !== undefined;
   290	  const hasFeedback = realOutcomes.length > 0;
   291	  const hasEnoughFeedback = hasEnoughRealData(realOutcomes);
   292	  const NUM_SYNTHETIC_LEARNERS = 3;
   293	  const benchmarkedTopics = hasLearnerContext && hasFeedback && !focusTopic
   294	    ? [...new Set(realOutcomes.map((outcome) => outcome.topic))].map((topic) => resolveTopic(topic))
   295	    : topics;
   296	
   297	  const topicBenchmarks = await Promise.all(
   298	    benchmarkedTopics.map(async (topic, index) => {
   299	      const topicReal = realOutcomes.filter((o) => o.topic === topic.slug);
   300	
   301	      let simulations: TeachingSimulation[];
   302	
   303	      if (hasLearnerContext) {
   304	        simulations = topicReal.length > 0
   305	          ? [computeRealOutcomeScore(topicReal, policy, topic, weights)]
   306	          : [];
   307	      } else {
   308	        const synthLearners = buildLearnerPopulation(seed + index * 97, NUM_SYNTHETIC_LEARNERS);
   309	        simulations = await Promise.all(
   310	          synthLearners.map((learner) =>
   311	            simulateTeaching(cwd, policy, topic, learner, weights)
