   314	      }
   315	
   316	      const summary = summarizeTopic(topic, simulations, traceLimit);
   317	      topicTraces.push({
   318	        topic: topic.title,
   319	        topLearners: summary.topLearners.map((entry) => ({
   320	          learnerId: entry.learner.id,
   321	          score: entry.score,
   322	          explanation: entry.explanation || ["unknown"]
   323	        })),
   324	        strugglingLearners: summary.strugglingLearners.map((entry) => ({
   325	          learnerId: entry.learner.id,
   326	          score: entry.score,
   327	          explanation: entry.explanation || ["unknown"]
   328	        })),
   329	        metricMeans: {
   330	          masteryGain: summary.meanMasteryGain,
   331	          retention: summary.meanRetention,
   332	          engagement: summary.meanEngagement,
   333	          transfer: summary.meanTransfer,
   334	          confusion: summary.meanConfusion
   335	        },
   336	        dominantStrength: summary.dominantStrength,
   337	        dominantWeakness: summary.dominantWeakness
   338	      });
   339	      return summary;
   340	    })
   341	  );
   342	
   343	  const weakest = [...topicBenchmarks].sort((left, right) => left.meanScore - right.meanScore)[0];
   344	
   345	  const overallScores = topicBenchmarks.map((entry) => entry.meanScore).filter(s => !Number.isNaN(s));
   346	  const dataSource = hasLearnerContext
   347	    ? hasFeedback
   348	      ? hasEnoughFeedback
   349	        ? "learner-feedback"
   350	        : "learner-feedback-sparse"
   351	      : "no-learner-feedback"
   352	    : "synthetic";
   353	
   354	  return {
   355	    policy,
   356	    suiteName: focusTopic ? `focused:${focusTopic}` : "core-suite",
   357	    topicBenchmarks,
   358	    overallScore: mean(overallScores),
   359	    weakestTopic: weakest?.topic.title ?? "n/a",
   360	    trace: {
   361	      seed,
   362	      learnerCountPerTopic: hasLearnerContext ? (hasFeedback ? 1 : 0) : NUM_SYNTHETIC_LEARNERS,
   363	      topicTraces,
   364	      realOutcomeCount: realOutcomes.length,
   365	      syntheticFallback: !hasLearnerContext,
   366	      dataSource,
   367	    }
   368	  };
   369	}
